import {BoxGeometry,Matrix4,Vector3} from 'three';
import {createMesh} from '../../shared/geometry.js';
import {emptyProject} from '../../shared/project.js';
const settings={printable_area:['0x0','250x0','250x210','0x210'],printable_height:'220',filament_settings_id:['PLA','PETG'],filament_colour:['#ff0000','#00ff00'],printer_technology:'FFF'};
export function fixture({parts=2,mirror=false}={}){const geometry=new BoxGeometry(10,10,10).toNonIndexed(),vertices=Array.from(geometry.attributes.position.array),triangles=Array.from({length:vertices.length/3},(_,i)=>i),objects=[];for(let inst=0;inst<2;inst++){const frame=new Matrix4().makeRotationZ(inst*Math.PI/2).setPosition(40+inst*60,40,10);if(inst&&mirror)frame.multiply(new Matrix4().makeScale(-1,1,1));for(let part=0;part<parts;part++){const component=new Matrix4().makeTranslation(part*14,0,0),combined=frame.clone().multiply(component),positions=[];for(let f=0;f<triangles.length;f+=3)for(const v of combined.determinant()<0?[0,2,1]:[0,1,2])positions.push(...new Vector3(...vertices.slice((f+v)*3,(f+v)*3+3)).applyMatrix4(combined).toArray());objects.push(createMesh({id:`i${inst}p${part}`,name:`Part ${part}`,plateId:'plate-1',positions,filamentSlot:1,painting:{version:1,winding:combined.determinant()<0?-1:1,color:{0:'4'}},native:{groupId:`group${inst}`,instanceFamily:'family',objectName:'Shared',partType:'normal_part',objectSettings:{},partSettings:{},meshSource:{version:1,vertices,triangles,component:component.toArray(),build:frame.toArray()}}}));}}return{...emptyProject(),nativeSettings:settings,objects,selectedId:'i0p0',selectedIds:['i0p0'],selectionScope:'part'};}
